"""Generate the browser catalogue from the server-owned command definitions."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
items = json.loads((ROOT / 'psexec_catalogue.json').read_text(encoding='utf-8'))
(ROOT / 'frontend/assets/psexec-catalogue.js').write_text(
    '// Generated by tools/build_psexec_catalogue.py. Edit psexec_catalogue.json.\n'
    + 'window.AtlasPsExecCatalogue = ' + json.dumps(items, ensure_ascii=True, indent=2) + ';\n',
    encoding='utf-8')
